            + '<input id="link_slide_' + item + '_' + lang_id + '" name="link_slide_' + item + '_' + lang_id + '"  type="text" />'
            + '</div>'
            + '</div>'
            + '</div>'
            + '<div class="large-12 small-12 columns">'
            + '<div class="row">'
