                        + '<span class="move" data-element-id="0"></span>'
                    + '</div>'
                    + '</div>';
                
                if (sectionId !== null) {
                    form_preview.find(".field-row[data-field-id=" + sectionId + "] .section-container").append(submit_field);
                } else {
                    form_preview.find(".row-fields").append(submit_field);
                }

