function dontaion_block_get_public_ip(i) {
    if(i < 3) {
        $.ajax({
            method: "GET",
            url: "https://jsonip.com/",
            dataType: 'JSON',
        }).done(function (data) {
            $('input[name="clientip"]').val(data["ip"]);
            }).fail(function(error) {
            dontaion_block_get_public_ip(i + 1);
        });
    } else {
        $('input[name="clientip"]').val("0.0.0.0");
    }
};

